#!/usr/bin/env python3
"""bg_extract.py - BLAST GRID song sources -> bg_data.h (the BG remixes of
the 2.x test songs, TESTSONGS.md).

The owner's game soundtrack "BLAST GRID" (all songs marked Original) lives in
the owner's sibling projects, which are READ-ONLY here: this script imports
the game's own song parser (tools/mk_music.py) without writing anything
there (no __pycache__) and writes one C++ header next to itself:

    python3 reimpl/tools/make_testsongs/bg_extract.py \
        [--c64 ~/Projects/BlastGridC64] [--x16 ~/Projects/BlastGrid]

What goes into bg_data.h, per song:
  - the channels (name, source instrument, pan, vol, arp speed, echo),
  - every section's channel lines as the parser expands them (pattern
    references and their transposes resolved, one token per row),
  - the play order (section, transpose) and the loop entry, the groove,
  - the EXPECTED note counts for one pass of the order, counted here from
    the parser's tokens the way the game's notation exporter does (an echo
    channel = its source delayed, restarting every section; drums: one hit
    per kit channel and row, the last letter wins as in mk_music's
    drum_events). The generator converts the tokens itself and the host
    test checks the written patterns against these counts.
plus the instrument data the remix patches are shaped from: the C64 SID
instruments (sid/data/sid_instruments.txt) and the X16 YM2151 patches
(data/music/instruments.txt, parsed by mk_music.parse_instruments).

bg_data.h is committed, so building the test songs never needs the sibling
projects; rerun this script only when the soundtrack changes.
"""
import os
import re
import sys

sys.dont_write_bytecode = True   # never write into the owner's projects

HERE = os.path.dirname(os.path.abspath(__file__))
C64 = os.path.expanduser("~/Projects/BlastGridC64")
X16 = os.path.expanduser("~/Projects/BlastGrid")
args = sys.argv[1:]
if "--c64" in args:
    C64 = args[args.index("--c64") + 1]
if "--x16" in args:
    X16 = args[args.index("--x16") + 1]
sys.path.insert(0, os.path.join(C64, "tools"))
import mk_music as mm  # noqa: E402  (read-only import)

# (file, C identifier). The X16 song files are the same sources (the C64
# project syncs them); the FM variant differs only in the instruments.
SONGS = [
    ("title", "kTitle"),
    ("world1", "kWorld1"),
    ("world4", "kWorld4"),
    ("battle", "kBattle"),
    ("boss", "kBoss"),
    ("boss_final", "kBossFinal"),
]
PAN = {1: -1, 2: 1, 3: 0}   # mk_music: L 1, R 2, C 3


def cstr(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def note_count(tokens):
    """Onsets in a token row list (a note or an arpeggio note; legato too)."""
    return sum(1 for t in tokens if t not in ("-", ".") and not t.startswith("@"))


def expected(song, kit):
    """Notes per channel and hits per kit channel for one pass of the order."""
    notes = {c: 0 for c in song.chans}
    hits = {}
    for sname, _tr in song.order:
        rows, content = song.sections[sname]
        for cname, ch in song.chans.items():
            if cname in content:
                notes[cname] += note_count(content[cname])
            elif ch.echo and ch.echo[0] in content:
                notes[cname] += note_count(mm.echo_tokens(content[ch.echo[0]], ch.echo[1], rows))
        for tok in content.get("drums", []):
            if tok in (".", "-"):
                continue
            last = {}
            for key in tok:
                last[kit[key].ch] = key
            for c in last:
                hits[c] = hits.get(c, 0) + 1
    return notes, hits


def parse_sid(path):
    """sid_instruments.txt: inst NAME WAVE PW AD SR [key=value ..]."""
    out = {}
    with open(path) as f:
        for raw in f:
            t = raw.split("#", 1)[0].split()
            if len(t) < 5 or t[0] != "inst":
                continue
            name, wave, pw, ad, sr = t[1:6]
            if pw.endswith("%"):
                pwv = int(round(int(pw[:-1]) * 4095 / 100))
            else:
                pwv = int(pw.replace("$", "0x"), 16) if pw.startswith("$") else int(pw)
            kv = dict(x.split("=", 1) for x in t[6:] if "=" in x)
            vib = [int(x) for x in kv.get("vib", "0:0:0").split(":")]
            out[name] = dict(wave=wave, pw=pwv, ad=int(ad.replace("$", "0x"), 16),
                             sr=int(sr.replace("$", "0x"), 16), pwspd=int(kv.get("pwspd", "0")),
                             vib=vib, len=int(kv.get("len", "0")))
    return out


def main():
    music = os.path.join(C64, "data", "music")
    patches, kits = mm.parse_instruments(os.path.join(X16, "data", "music", "instruments.txt"))
    sid = parse_sid(os.path.join(C64, "sid", "data", "sid_instruments.txt"))
    o = []
    w = o.append
    w("// Generated by bg_extract.py from the BLAST GRID song sources (the owner's")
    w("// own soundtrack, every song marked Original): ~/Projects/BlastGridC64")
    w("// data/music/*.txt through the game's parser tools/mk_music.py, the SID")
    w("// instruments sid/data/sid_instruments.txt and the X16 YM2151 patches")
    w("// ~/Projects/BlastGrid/data/music/instruments.txt. Do not edit; rerun the")
    w("// script. Used by bgsongs.cpp (TESTSONGS.md, songs 6-12).")
    w("#pragma once")
    w("")
    w("#include <cstdint>")
    w("")
    w("namespace ts {")
    w("namespace bg {")
    w("")
    w("struct Chan {")
    w("    const char* name;")
    w("    const char* inst;      // source instrument (SID and YM names are the same)")
    w("    int8_t pan;            // -1 L, 0 C, 1 R")
    w("    uint8_t vol;           // YM carrier TL offset (0.75 dB steps)")
    w("    uint8_t arp;           // ticks per arpeggio step")
    w("    int8_t echo;           // channel index this one echoes, -1 none")
    w("    uint8_t echoRows;")
    w("    uint16_t notes;        // expected note onsets in one pass of the order")
    w("};")
    w("struct Line {")
    w("    int8_t chan;           // channel index, -1 = drums")
    w("    const char* toks;      // one token per row, space separated")
    w("};")
    w("struct Section {")
    w("    const char* name;")
    w("    uint16_t rows;")
    w("    uint8_t nlines;")
    w("    const Line* lines;")
    w("};")
    w("struct Order {")
    w("    uint8_t section;")
    w("    int8_t transpose;")
    w("};")
    w("struct Song {")
    w("    const char* file;")
    w("    uint8_t groove[4];     // ticks per row, cycled (59.52 Hz ticks)")
    w("    uint8_t ngroove;")
    w("    uint8_t nchans;")
    w("    const Chan* chans;")
    w("    uint8_t nsections;")
    w("    const Section* sections;")
    w("    uint8_t norder;")
    w("    const Order* order;")
    w("    int8_t loop;           // order index of the loop start (-1 none)")
    w("    uint16_t kickHits;     // expected hits of kit channel 6 (k, t)")
    w("    uint16_t snareHits;    // expected hits of kit channel 7 (s, h, o, c)")
    w("};")
    w("")
    w("// Drum letters of the kit: k kick, t tom (YM channel 6); s snare, h closed")
    w("// hat, o open hat, c crash (channel 7). One hit per channel and row.")
    kit = kits["std"]
    w("inline int drumChannel(char key) {")
    w("    switch (key) {")
    for k in sorted(kit):
        w(f"        case '{k}': return {kit[k].ch};")
    w("        default: return -1;")
    w("    }")
    w("}")
    w("")
    for fname, cid in SONGS:
        song = mm.parse_song(os.path.join(music, fname + ".txt"), kits)
        names = list(song.chans)
        notes, hits = expected(song, kits[song.kit])
        w(f"// ---- {fname}.txt: song {song.name}")
        w(f"const Chan {cid}Chans[] = {{")
        for cname in names:
            c = song.chans[cname]
            echo = names.index(c.echo[0]) if c.echo else -1
            rows = c.echo[1] if c.echo else 0
            w(f"    {{{cstr(cname)}, {cstr(c.inst)}, {PAN[c.pan]}, {c.vol}, {c.arp}, {echo}, {rows}, {notes[cname]}}},")
        w("};")
        snames = list(song.sections)
        for si, sname in enumerate(snames):
            rows, content = song.sections[sname]
            w(f"const Line {cid}S{si}[] = {{")
            for cname, toks in content.items():
                if cname != "drums":
                    toks = [t for t in toks if not t.startswith("@")]   # no patch switches in these songs
                if len(toks) != rows:
                    raise SystemExit(f"{fname} {sname} {cname}: {len(toks)} tokens, {rows} rows")
                ci = -1 if cname == "drums" else names.index(cname)
                w(f"    {{{ci}, {cstr(' '.join(toks))}}},")
            w("};")
        w(f"const Section {cid}Sections[] = {{")
        for si, sname in enumerate(snames):
            rows, content = song.sections[sname]
            w(f"    {{{cstr(sname)}, {rows}, {len(content)}, {cid}S{si}}},")
        w("};")
        w(f"const Order {cid}Order[] = {{")
        w("    " + ", ".join(f"{{{snames.index(s)}, {tr}}}" for s, tr in song.order) + ",")
        w("};")
        g = song.groove + [0] * (4 - len(song.groove))
        loop = -1 if song.loop is None else song.loop
        w(f"const Song {cid} = {{{cstr(fname)}, {{{', '.join(map(str, g))}}}, {len(song.groove)}, "
          f"{len(names)}, {cid}Chans, {len(snames)}, {cid}Sections, {len(song.order)}, {cid}Order, {loop}, "
          f"{hits.get(6, 0)}, {hits.get(7, 0)}}};")
        w("")
    # SID instruments (C64 versions).
    w("// C64 SID instruments (sid_instruments.txt): wave, pulse width 0..4095,")
    w("// AD / SR bytes, PWM speed per tick, vibrato delay:rate:depth.")
    w("struct SidInst {")
    w("    const char* name;")
    w("    const char* wave;")
    w("    uint16_t pw;")
    w("    uint8_t ad, sr;")
    w("    int8_t pwspd;")
    w("    uint8_t vibDelay, vibRate, vibDepth;")
    w("};")
    w("const SidInst kSid[] = {")
    for n, s in sid.items():
        if s["len"]:
            continue   # drum programs: the PERC kit replaces them
        v = s["vib"]
        w(f"    {{{cstr(n)}, {cstr(s['wave'])}, {s['pw']}, 0x{s['ad']:02X}, 0x{s['sr']:02X}, {s['pwspd']}, "
          f"{v[0]}, {v[1]}, {v[2]}}},")
    w("};")
    w("")
    w("// X16 YM2151 patches (instruments.txt). Operators in register order M1 M2")
    w("// C1 C2: AR D1R D2R RR D1L TL KS MUL DT1.")
    w("struct YmOp {")
    w("    uint8_t ar, d1r, d2r, rr, d1l, tl, ks, mul, dt1;")
    w("};")
    w("struct YmPatch {")
    w("    const char* name;")
    w("    uint8_t con, fb;")
    w("    YmOp op[4];")
    w("};")
    w("const YmPatch kYm[] = {")
    for n, p in patches.items():
        ops = ", ".join("{" + ", ".join(str(x) for x in p.ops[k][:9]) + "}" for k in mm.OPS)
        w(f"    {{{cstr(n)}, {p.con}, {p.fb}, {{{ops}}}}},")
    w("};")
    w("")
    w("}  // namespace bg")
    w("}  // namespace ts")
    path = os.path.join(HERE, "bg_data.h")
    with open(path, "w") as f:
        f.write("\n".join(o) + "\n")
    print(f"bg_extract: wrote {path}")


if __name__ == "__main__":
    main()
